            // For ghp etc, minimal length is 36, we truncate to 36 if longer
            // For npm, 36
            // For SK, 32? But SK pattern is SK + 32, minimal 32, but our regex matches longer, we truncate to 32?
            // For now, truncate to minimal length for those patterns by checking prefix
            if strings.HasPrefix(m, "ghp_") || strings.HasPrefix(m, "gho_") || strings.HasPrefix(m, "ghu_") || strings.HasPrefix(m, "ghs_") || strings.HasPrefix(m, "ghr_") {
                if len(m) > 4+36 {
                    truncated = m[:4+36]
                }
            } else if strings.HasPrefix(m, "github_pat_") {
                if len(m) > 11+36 {
                    truncated = m[:11+36]
                }
            } else if strings.HasPrefix(m, "glpat-") {
                if len(m) > 6+20 {
                    // glpat minimal 20, but longer should be truncated to 20? Or keep full? For glpat, we saw not truncated? Let's keep full for now
                }
            } else if strings.HasPrefix(m, "npm_") {
                if len(m) > 4+36 {
                    truncated = m[:4+36]
                }
            } else if strings.HasPrefix(m, "SK") {
                if len(m) > 2+32 {
                    truncated = m[:2+32]
                }
            } else if strings.HasPrefix(m, "sk_live_") {
                if len(m) > 8+24 {
                    // For sk_live, we saw 30 not truncated, so keep full? Actually sk_live 30 gave 30 not 24, so keep full
                }
            } else if strings.HasPrefix(m, "rk_live_") {
                // keep full
            } else if strings.HasPrefix(m, "xox") {
                // For xox, we saw longer truncated? For xoxb- with long suffix, only-matching gave truncated to first two segments? Actually xoxb- long gave "xoxb-123456789012-1234567890123" truncated? Let's see: xoxb longer only gave "xoxb-123456789012-1234567890123" (two segments) not full third. So for xox, we should truncate to first 2 segments? Hard to replicate.
                // For now keep full match
            } else if strings.HasPrefix(m, "AIzaSy") {
                if len(m) > 6+33 {
                    truncated = m[:6+33]
                }
            }
            hasSecret = true
            matchedValues = append(matchedValues, truncated)
        }
    }
    // Check private key suffix
    trimmedLine := strings.TrimRight(line, "\r\n")
    // Check if line ends with private key pattern
    if privateKeyRegex.MatchString(trimmedLine) {
        // Extract the private key part
        m := privateKeyRegex.FindString(trimmedLine)
        if m != "" && !shouldIgnoreSecret(m) {
            hasSecret = true
            matchedValues = append(matchedValues, m)
        }
    } else {
        // Also check for PGP variant
        if strings.HasSuffix(trimmedLine, "-----BEGIN PGP PRIVATE KEY BLOCK-----") {
            m := "-----BEGIN PGP PRIVATE KEY BLOCK-----"
            if !shouldIgnoreSecret(m) {
                hasSecret = true
                matchedValues = append(matchedValues, m)
            }
        }
    }
    // Check assignment
    // Find all assignments
    // Use assignmentRegex to find matches
    // assignmentRegex has 2 groups: keyword and secret
    allAssignMatches := assignmentRegex.FindAllStringSubmatch(line, -1)
    for _, groups := range allAssignMatches {
        if len(groups) < 3 {
            continue
        }
        secret := groups[2]
        // Need to strip trailing quotes/brackets?
        // The regex already captures without quotes, but may include trailing chars like , or ;
        // Trim non-alnum suffix
        // For now, secret is captured as is
        if !isRandom(secret) {
            continue
        }
        if shouldIgnoreSecret(secret) {
            continue
        }
        hasSecret = true
        matchedValues = append(matchedValues, secret)
    }
    // Check additional patterns
    for _, re := range additionalRegexes {
        matches := re.FindAllStringSubmatch(line, -1)
        for _, groups := range matches {
            var secret string
            hasGroup := false
            if len(groups) > 1 {
                // Check if pattern has capturing group
                // groups[1] is first capturing group
                secret = groups[1]
                hasGroup = true
                // If capturing group is empty, skip?
                if secret == "" {
                    // Find next non-empty group?
                    for i := 1; i < len(groups); i++ {
                        if groups[i] != "" {
                            secret = groups[i]
                            break
                        }
                    }
                }
            } else {
                // No capturing group, whole match
                secret = groups[0]
                hasGroup = false
            }
            if hasGroup {
                // Test randomness
                if !isRandom(secret) {
                    continue
                }
            }
            if shouldIgnoreSecret(secret) {
                continue
            }
            // For additional without group, secret is whole match
            // For with group, secret is group
            hasSecret = true
            matchedValues = append(matchedValues, secret)
        }
    }
    return hasSecret, matchedValues
}

var additionalRegexes []*regexp.Regexp

func scanFile(path string, onlyMatching bool) (found bool, outputs []string) {
    data, err := os.ReadFile(path)
    if err != nil {
        return false, nil
    }
    // Check if file is .secretsignore, skip? Or still scan? We'll skip scanning .secretsignore itself to avoid false positives from ignore patterns.
    // But if file is explicitly passed and is .secretsignore, we should still scan? For now, skip if base is .secretsignore and we are walking (but explicit will still scan if passed as source)
    content := string(data)
    // Split handling both \n and \r\n
    lines := strings.Split(content, "\n")
    for i, rawLine := range lines {
        // rawLine still has possible \r
        line := strings.TrimRight(rawLine, "\r")
        // Note: original prints line as is without \r, but includes content as read
        hasSecret, matched := findSecretsInLine(line)
        if hasSecret {
            found = true
            if onlyMatching {
                for _, m := range matched {
                    outputs = append(outputs, fmt.Sprintf("%s:%d:%s", path, i+1, m))
                }
            } else {
                outputs = append(outputs, fmt.Sprintf("%s:%d:%s", path, i+1, line))
                // Only one output per line even if multiple matches, so break after first line's hasSecret?
                // But we already aggregated matched for onlyMatching; for normal, we should output line once.
                // So we should not output multiple times per line for normal.
            }
        }
    }
    return found, outputs
}

func printHelpShort() {
    fmt.Print(`A command-line tool to prevent committing secret keys into your source code

Usage: executable [OPTIONS] [Source files]...

Arguments:
  [Source files]...  Source files. Can be files or directories. Defaults to '.'

Options:
      --install-pre-commit
          Install `+"`ripsecrets`"+` as a pre-commit hook automatically in git directory provided
      --strict-ignore
          If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit
      --only-matching
          Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line
      --additional-pattern <ADDITIONAL_PATTERNS>
          Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret
  -h, --help
          Print help (see more with '--help')
  -V, --version
          Print version
`)
}

