func main() {
    initRegexes()
    args := os.Args[1:]
    var installPreCommit bool
    var strictIgnore bool
    var onlyMatching bool
    var additionalPatterns []string
    var sources []string
    var showHelpShort bool
    var showHelpLong bool
    var showVersion bool

    i := 0
    for i < len(args) {
        arg := args[i]
        if arg == "--install-pre-commit" {
            installPreCommit = true
            i++
        } else if arg == "--strict-ignore" {
            strictIgnore = true
            i++
        } else if arg == "--only-matching" {
            onlyMatching = true
            i++
        } else if arg == "--additional-pattern" {
            if i+1 >= len(args) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            additionalPatterns = append(additionalPatterns, args[i+1])
            i += 2
        } else if strings.HasPrefix(arg, "--additional-pattern=") {
            val := strings.TrimPrefix(arg, "--additional-pattern=")
            if val == "" {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            additionalPatterns = append(additionalPatterns, val)
            i++
        } else if arg == "-h" {
            showHelpShort = true
            i++
        } else if arg == "--help" {
            showHelpLong = true
            i++
        } else if arg == "-V" || arg == "--version" {
            showVersion = true
            i++
        } else if strings.HasPrefix(arg, "-") {
            // unknown
