func isRandom(s string) bool {
    if len(s) < 8 {
        return false
    }
    // quick check for repeated char
    // Shannon entropy
    freq := make(map[rune]int)
    for _, c := range s {
        freq[c]++
    }
    entropy := 0.0
    l := float64(len(s))
    for _, count := range freq {
        p := float64(count) / l
        entropy -= p * math.Log2(p)
    }
    // thresholds based on observed
    // For assignment, we need to be permissive for high entropy
    // Use threshold 2.5 for now
    if entropy < 2.8 {
        return false
    }
    // Additional check: if string is all same case lower and long, still consider random if entropy high? We'll allow.
    return true
}

func matchesPattern(pattern, path string) bool {
    pattern = strings.TrimPrefix(pattern, "/")
    // Handle ** -> treat as *
    pattern = strings.ReplaceAll(pattern, "**", "*")
    if strings.HasSuffix(pattern, "/") {
        dir := strings.TrimSuffix(pattern, "/")
        if path == dir || strings.HasPrefix(path, dir+"/") {
            return true
        }
        // also check if dir appears as component
        parts := strings.Split(path, "/")
        for _, p := range parts {
            if ok, _ := filepath.Match(dir, p); ok {
                // check if path is inside that dir? For pattern "a/" and path "sub/a/file", should match?
                // For our simple case, check prefix
                if strings.Contains(path, dir+"/") {
                    return true
                }
            }
        }
        return false
    }
    if strings.Contains(pattern, "/") {
        matched, _ := filepath.Match(pattern, path)
        if matched {
            return true
        }
        return false
    } else {
        // no slash, match basename or any component
        base := filepath.Base(path)
        if matched, _ := filepath.Match(pattern, base); matched {
            return true
        }
        // Also check directory components for patterns like "ignored_dir"
        parts := strings.Split(path, "/")
        for _, part := range parts {
            if matched, _ := filepath.Match(pattern, part); matched {
                return true
            }
        }
        // For patterns like "a.txt" which should match "sub/a.txt", base already handled
        return false
    }
}

func isIgnoredFile(path string) bool {
    normalized := strings.TrimPrefix(path, "./")
    ignored := false
    for _, pat := range filePatterns {
        if pat == "" {
            continue
        }
        if strings.HasPrefix(pat, "!") {
            actual := strings.TrimPrefix(pat, "!")
            if matchesPattern(actual, normalized) {
                ignored = false
            }
        } else {
            if matchesPattern(pat, normalized) {
                ignored = true
            }
        }
    }
    return ignored
}

func loadIgnore() {
